    private Icons() {
    }

    /**
     * Creates an icon node. It is a Region whose shape is the SVG path, so its
     * colour comes from -fx-background-color in CSS (class "icon").
     */
    public static Node create(String svgPath, double size) {
        Region region = new Region();
        region.setStyle("-fx-shape: \"" + svgPath + "\";");
        region.getStyleClass().add("icon");
        region.setMinSize(size, size);
        region.setPrefSize(size, size);
        region.setMaxSize(size, size);
        return region;
    }
